.dwe-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwe-root,.dwe-root *,.dwe-root *::before,.dwe-root *::after{box-sizing:border-box}
.dwe-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwe-root img{display:block;border:0;max-width:none}
.dwe-root > [data-node-id]{will-change:transform}
.dwe-root [hidden]{display:none!important}
.dwe-root [data-sh-theme="dark"]{display:none!important}
.dwe-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwe-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwe-root .n28_2851{background-color:var(--wa-point, #3967fd);align-content:stretch;display:flex;gap:8px;align-items:center;justify-content:center;padding-left:18px;padding-right:18px;padding-top:8px;padding-bottom:8px;position:relative;border-radius:6px;flex-shrink:0}
.dwe-root .nI28_2851_1_3386{position:relative;flex-shrink:0;width:13px;height:13px}
.dwe-root .x22{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dwe-root .nI28_2851_1_3387{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:normal;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #fcfcfc);font-size:11.3px;letter-spacing:-0.226px;white-space:nowrap}
