.dwe-root[data-theme="dark"] [data-name="Input"],.dwe-root[data-theme="dark"] [data-name="Select"],.dwe-root[data-theme="dark"] [data-name^="Field/ID"],.dwe-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
